{"filename":"style.css","content":"/* SimpleTaskTracker – responsive styling */
:root {
  --accent:#336699;
  --bg:#ffffff;
  --text:#333333;
  --header-bg:#f5f5f5;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg:#121212;
    --text:#eeeeee;
    --header-bg:#1e1e1e;
  }
}
body {
  margin:0;
  font-family:system-ui, sans-serif;
  background:var(--bg);
  color:var(--text);
  line-height:1.5;
}
header {
  background:var(--header-bg);
  padding:1rem;
  text-align:center;
  border-bottom:1px solid #ddd;
}
nav ul {
  list-style:none;
  display:flex;
  justify-content:center;
  padding:0;
  margin:0;
  background:var(--header-bg);
}
nav li {
  margin:0 0.5rem;
}
nav a {
  text-decoration:none;
  color:var(--accent);
  padding:0.5rem 1rem;
  border-radius:4px;
}
nav a:hover,
nav a.active {
  background:var(--accent);
  color:#fff;
}
main {
  padding:1rem;
  max-width:1200px;
  margin:auto;
}
.view {
  display:none;
}
.view.active {
  display:block;
}
#task-table {
  width:100%;
  border-collapse:collapse;
  margin-top:1rem;
}
#task-table th,
#task-table td {
  border:1px solid #ccc;
  padding:0.5rem;
  text-align:left;
}
#task-table th {
  background:var(--header-bg);
}
button,
input,
select,
textarea {
  font:inherit;
}
button {
  background:var(--accent);
  color:#fff;
  border:none;
  padding:0.5rem 1rem;
  border-radius:4px;
  cursor:pointer;
}
button:hover {
  background:#2a5580;
}
button:disabled {
  opacity:0.6;
  cursor:not-allowed;
}
input,
select,
textarea {
  border:1px solid #ccc;
  border-radius:4px;
  padding:0.4rem;
  width:100%;
  box-sizing:border-box;
}
.empty-state {
  text-align:center;
  color:#777;
  margin-top:2rem;
}
/* Focus visible for accessibility */
:focus-visible {
  outline:2px solid var(--accent);
  outline-offset:2px;
}
/* Responsive adjustments */
@media (max-width:768px) {
  nav ul {
    flex-direction:column;
  }
  nav a {
    display:block;
    margin:0.2rem 0;
  }
  /* Collapse table into list cards */
  #task-table thead {
    display:none;
  }
  #task-table,
  #task-table tbody,
  #task-table tr,
  #task-table td {
    display:block;
    width:100%;
  }
  #task-table tr {
    margin-bottom:1rem;
    border:1px solid #ccc;
    border-radius:4px;
    overflow:hidden;
  }
  #task-table td {
    text-align:right;
    padding-left:50%;
    position:relative;
  }
  #task-table td::before {
    content:attr(data-label);
    position:absolute;
    left:0;
    width:45%;
    padding-left:0.5rem;
    font-weight:bold;
    text-align:left;
    color:#555;
  }
}
"}
